#!/usr/bin/env bash
# Generated by Capsules (template 1.2.0).
# Prepares the per-capsule tool-state volumes. Safe to run any number of times.
# Claude Code keeps its global state in $CLAUDE_CONFIG_DIR/.claude.json, inside
# the ~/.claude volume, so it survives rebuilds without a link. A stray
# ~/.claude.json (written before CLAUDE_CONFIG_DIR applied) is moved into the
# volume when the volume has none yet. Nothing is ever deleted.
set -euo pipefail

claude_config_dir="${CLAUDE_CONFIG_DIR:-$HOME/.claude}"

# Docker creates a named volume's mount point as root when the image has no
# such directory. Hand each one to the development user.
workspace_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
for dir in "$claude_config_dir" "$HOME/.codex" "$HOME/.copilot" "$workspace_dir/node_modules"; do
  if [ ! -d "$dir" ]; then
    mkdir -p "$dir"
  fi
  if [ ! -O "$dir" ]; then
    # -n: never prompt; the base image's vscode user has passwordless sudo.
    sudo -n chown "$(id -u):$(id -g)" "$dir" || echo "warning: could not take ownership of $dir" >&2
  fi
done

home_state="$HOME/.claude.json"
volume_state="$claude_config_dir/.claude.json"
if [ -f "$home_state" ] && [ ! -L "$home_state" ] && [ "$home_state" != "$volume_state" ]; then
  if [ -e "$volume_state" ]; then
    echo "note: $home_state is not used while $volume_state exists; left unchanged" >&2
  else
    mv "$home_state" "$volume_state"
    echo "claude.json: moved into the $claude_config_dir volume"
  fi
fi
